nativeHeapAbiV48 {
    fn:
        identity(value >> u64) -> u64 { return value; }
        fill(block >> p<byte>, bytes >> u64) -> bool {
            index >> u64 <- 0;
            while (index < bytes) { wr(off(block,index),index & 255); index += 1; }
            return true;
        }
        check(block >> p<byte>, bytes >> u64) -> bool {
            index >> u64 <- 0;
            while (index < bytes) {
                if (rd(off(block,index)) != (index & 255)) return false;
                index += 1;
            }
            return true;
        }
        run() -> int {
            if (!free(null)) return 1;
            if (alloc(identity(0x8000000000000000)) != null) return 2;
            if (calloc(identity(0x100000000),identity(0x100000000)) != null) return 3;
            empty >> p<byte> <- calloc(identity(0xFFFFFFFFFFFFFFFF),0);
            if (empty == null || !free(empty)) return 4;
            block >> p<byte> <- realloc(null,512);
            address >> u64 <- adr(block);
            if (block == null || (address & 15) != 0) return 5;
            fill(block,512);
            failed >> p<byte> <- realloc(block,identity(0xFFFFFFFFFFFFFFFF));
            if (failed != null || !check(block,512)) { free(block); return 6; }
            grown >> p<byte> <- realloc(block,4096);
            if (grown == null) { free(block); return 7; }
            if (!check(grown,512)) { free(grown); return 8; }
            small >> p<byte> <- realloc(grown,32);
            if (small == null) { free(grown); return 9; }
            if (!check(small,32)) { free(small); return 10; }
            if (realloc(small,0) != null) return 11;
            iteration >> int <- 0;
            while (iteration < 2000) {
                cells >> p<u64> <- cast<u64>(calloc(16,8));
                if (cells == null) return 12;
                index >> int <- 0;
                while (index < 16) {
                    if (rd(off(cells,index)) != 0) { free(cells); return 13; }
                    wr(off(cells,index),0x100000000+index); index += 1;
                }
                if (rd(off(cells,15)) != 0x10000000F || !free(cells)) return 14;
                iteration += 1;
            }
            return 71;
        }
    ref main ->> run;
    fa:
        return true;
}

nativeHeapAllocV48 {
    run() -> int {
        cell >> p<u64> <- cast<u64>(alloc(8));
        if (cell == null) return 1;
        wr(cell,0x10000002A);
        value >> u64 <- rd(cell);
        released >> bool <- free(cell);
        return value == 0x10000002A && released ? 72 : 2;
    }
    ref main ->> run;
    fa: return true;
}

nativeHeapCallocV48 {
    run() -> int {
        cells >> p<u64> <- cast<u64>(calloc(4,8));
        if (cells == null) return 1;
        index >> int <- 0;
        while (index < 4) {
            if (rd(off(cells,index)) != 0) { free(cells); return 2; }
            index += 1;
        }
        wr(off(cells,3),0x123456789ABCDEF);
        value >> u64 <- rd(off(cells,3));
        return free(cells) && value == 0x123456789ABCDEF ? 73 : 3;
    }
    ref main ->> run;
    fa: return true;
}

nativeHeapEmptyV48 {
    run() -> int {
        empty >> p<byte> <- alloc(0);
        if (empty == null) return 1;
        zeroed >> p<byte> <- calloc(0,0xFFFFFFFFFFFFFFFF);
        if (zeroed == null) { free(empty); return 2; }
        return free(empty) && free(zeroed) && free(null) ? 74 : 3;
    }
    ref main ->> run;
    fa: return true;
}

nativeHeapOverflowV48 {
    identity(bytes >> u64) -> u64 { return bytes; }
    run() -> int {
        a >> p<byte> <- alloc(identity(0xFFFFFFFFFFFFFFFF));
        b >> p<byte> <- calloc(identity(0x100000000),identity(0x100000000));
        c >> p<byte> <- calloc(1,identity(0xFFFFFFFFFFFFFFFF));
        ok >> bool <- a == null && b == null && c == null;
        free(a); free(b); free(c);
        return ok ? 75 : 1;
    }
    ref main ->> run;
    fa: return true;
}

nativeHeapNestedV48 {
    make(bytes >> u64) -> p<byte> { return alloc(bytes); }
    release(pointer >> p<byte>) -> bool { return free(pointer); }
    run() -> int {
        left >> p<u64> <- cast<u64>(make(8));
        right >> p<u64> <- cast<u64>(make(8));
        if (left == null || right == null) { release(left); release(right); return 1; }
        wr(left,0x100000000); wr(right,0x10000000A);
        value >> u64 <- rd(left)+rd(right);
        return release(left) && release(right) && value == 0x20000000A ? 76 : 2;
    }
    ref main ->> run;
    fa: return true;
}

nativeHeapShadowV48 {
    alloc(value >> int) -> int { return value+1; }
    calloc(left >> int, right >> int) -> int { return left+right; }
    free(value >> int) -> int { return value-1; }
    realloc(left >> int, right >> int) -> int { return left*right; }
    run() -> int { return alloc(7)+calloc(9,10)+free(21)+realloc(3,10); }
    ref main ->> run;
    fa: return true;
}
